// scripts/tests/unit/release-stage-preflight-artifact.test.ts — issue 1272's
// proof that the refactored runner runs against a stage target built by
// `stage-target up --dump` from a production dump under 24 hours old: the
// preflight journal of `bun run release:run --target stage --preflight`,
// committed under scripts/tests/fixtures/release/, records the new step-list
// hash, a commit, and every remote step ok (R1.1 to R2.5).
//
// The fixture is the artifact of one run, never regenerated by CI. When the
// step list changes, the hash here changes too, and a new stage preflight must
// be run and committed: that is the point.
import { describe, expect, test } from "bun:test";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { preflightSteps, type PreflightReport } from "../../release/preflight.ts";
import { RELEASE_STEPS, stepListHash } from "../../release/steps.ts";

const dir = join(import.meta.dir, "..", "fixtures", "release");

describe("the committed stage preflight journal (issue 1272)", () => {
  const files = readdirSync(dir).filter((n) => /^stage-preflight-\d{8}T\d{6}Z\.json$/.test(n)).sort();

  test("at least one journal is committed", () => {
    expect(files.length).toBeGreaterThan(0);
  });

  test("the newest journal records the current step-list hash, the commit and every remote step ok", () => {
    const report = JSON.parse(readFileSync(join(dir, files.at(-1)!), "utf8")) as PreflightReport;
    expect(report.kind).toBe("preflight");
    expect(report.target).toBe("stage");
    expect(report.rmEnv).toBe("stage");
    expect(report.stepListHash).toBe(stepListHash());
    expect(report.commit).toMatch(/^[0-9a-f]{40}$/);
    expect(report.checks.find((c) => c.id === "P.commit")?.status).toBe("green");
    const ids = preflightSteps(RELEASE_STEPS).map((s) => s.id);
    expect(ids).toEqual(["R1.1", "R1.2", "R1.3", "R1.4", "R1.5", "R1.6", "R2.1", "R2.2", "R2.4r", "R2.3", "R2.5"]);
    for (const id of ids) {
      expect(report.steps[id]?.status, id).toBe("ok");
      expect(report.checks.find((c) => c.id === id)?.status, id).toBe("green");
    }
    // red control: a journal at another hash, or with one step failed, is not this proof.
    expect({ ...report, stepListHash: "0".repeat(64) }.stepListHash).not.toBe(stepListHash());
    expect(Object.values(report.steps).some((s) => s.status === "failed")).toBe(false);
  });
});
